const ruPlural = (count: number, one: string, few: string, many: string) =>
  count % 10 === 1 && count % 100 !== 11
    ? one
    : [2, 3, 4].includes(count % 10) && ![12, 13, 14].includes(count % 100)
      ? few
      : many;

